let lang=LANGS.includes(new URLSearchParams(location.search).get('lang'))?new URLSearchParams(location.search).get('lang'):'en';
let data,limit=20;const $=id=>document.getElementById(id),t=i=>WORDS[lang][i],esc=x=>String(x??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
function safeURL(s){try{const u=new URL(s);return u.protocol==='https:'?esc(u.href):'#'}catch{return '#'}}
function date(s){return s&&Number.isFinite(Date.parse(s))?new Intl.DateTimeFormat(lang,{dateStyle:'medium',timeStyle:'short',timeZone:'Europe/Istanbul'}).format(new Date(s))+' · UTC+3':'—'}
function text(id,s){$(id).textContent=s}
function dataURL(name){return window.COP31_DATA?.[name]||name+'.json'}
function standing(d){return /informal/i.test(d.type)?t(17):/draft/i.test(d.type)?t(16):t(18)}
function sourceTitle(x){return x.title_i18n?.[lang]||x.title||''}function description(x){return x.description_i18n?.[lang]||x.summary_i18n?.[lang]||x.description||x.summary||''}
function story(x,lead=false){return `<span class="source-type">${esc(x.content_type==='official'?t(13):t(14))}</span><${lead?'h2':'h3'}><a href="${safeURL(x.url)}">${esc(sourceTitle(x))}</a></${lead?'h2':'h3'}><p>${esc(description(x))}</p><p class="meta">${esc(x.publisher)} · ${esc(x.published||'')}</p>`}
function normalizeDocuments(v){if(!Array.isArray(v.documents))throw Error('documents');return {...v,documents:v.documents.map(d=>{const attachments=Array.isArray(d.attachments)?d.attachments:[],a=attachments.find(x=>/^(en|english)$/i.test(x.language||''))||attachments[0];return {...d,symbol:d.symbol||d.document_code||'',published:d.published??d.published_at??null,version:d.version??d.metadata_version,url:d.url||a?.url||d.source_url||'',is_pdf:d.is_pdf??!!(a||d.url),type:d.type||d.status||'',agenda:d.agenda||''}})}}
function activeDocuments(){return data.documents.documents.filter(d=>!d.withdrawn&&!d.withdrawn_at&&d.status!=='withdrawn')}
function newestDocument(a,b){return (Date.parse(b.published)||0)-(Date.parse(a.published)||0)}
function searchText(value){return String(value??'').normalize('NFD').replace(/\p{M}/gu,'').toLowerCase()}
function documentMatches(d,query){const haystack=searchText([d.title,d.symbol,d.body,d.agenda].filter(Boolean).join(' '));return searchText(query).trim().split(/\s+/u).filter(Boolean).every(term=>haystack.includes(term))}
function docs(){let q=$('search').value,b=$('body').value;let rows=activeDocuments().filter(d=>(!b||d.body===b)&&documentMatches(d,q)).sort(newestDocument);text('count',`${rows.length} ${t(33)}`);$('documents').innerHTML=rows.slice(0,limit).map(d=>`<article class="document"><div><p class="symbol" dir="ltr">${esc(d.symbol)} · ${esc(d.body)} · ${esc(t(32))} ${esc(d.agenda)}</p><h2 lang="en" dir="auto">${esc(d.title)}</h2><span class="badge">${esc(standing(d))}</span><span class="badge">${esc(t(19))}</span><p class="meta">${esc(t(21))}: ${esc(date(d.published))}</p>${d.notes?`<p class="notes" lang="en" dir="auto">${esc(d.notes.replace(/<[^>]*>/g,''))}</p>`:''}</div><div class="actions"><span>${esc(t(20))}: ${esc(d.version??'—')} <small>(${esc(t(36))})</small></span><a href="${safeURL(d.url)}">${esc(d.is_pdf===false?t(37):t(15))} ↗</a><span class="subtle">${esc(t(35))}</span></div></article>`).join('')||`<p>${esc(t(30))}</p>`;$('more').hidden=rows.length<=limit;}
function render(){document.documentElement.lang=lang;document.documentElement.dir=lang==='ar'?'rtl':'ltr';$('language').value=lang;document.querySelectorAll('[data-tab]').forEach((a,i)=>a.textContent=t(i));text('prototype',t(4));text('today-title',t(5));text('recent-title',t(6));text('all-texts',t(7));text('texts-title',t(8));text('search-label',t(9));text('body-label',t(10));text('reset',t(11));text('more',t(12));text('pulse-title',t(24));text('pulse-intro',t(25)+' '+t(31));text('explore-title',t(26));text('production',t(27));text('theme',document.body.classList.contains('dark')?t(29):t(28));text('texts-intro',t(31));text('edition',`ANTALYA · ${data.briefing.edition}`);text('today-status',t(34)+': '+date(data.briefing.collection?.web_round));text('doc-status',t(22)+': '+date(data.documents.checked_at)+'. '+t(23));text('texts-status',$('doc-status').textContent);let stories=data.briefing.sections?.essential||[];$('lead').innerHTML=stories.length?story(stories[0].lead,true):esc(t(30));$('signals').innerHTML=stories.slice(1,4).map(x=>`<article class="signal">${story(x.lead)}</article>`).join('');$('recent').innerHTML=[...activeDocuments()].sort(newestDocument).slice(0,3).map(d=>`<article class="recent-item"><p class="meta">${esc(d.body)} · ${esc(standing(d))}</p><a lang="en" dir="auto" href="${safeURL(d.url)}">${esc(d.title)}</a><p class="meta">${esc(date(d.published))}</p></article>`).join('');let old=$('body').value;$('body').innerHTML='<option value="">'+esc(t(1))+' · '+esc(t(10))+'</option>'+[...new Set(data.documents.documents.map(x=>x.body))].sort().map(x=>`<option>${esc(x)}</option>`).join('');$('body').value=old;docs();$('posts').innerHTML=data.pulse.items.slice(0,12).map(x=>`<article class="post"><span class="source-type">${esc(x.platform||'Social')}</span><p dir="auto">${esc(x.title||x.summary||x.text||'')}</p><p class="meta">${esc(x.publisher||x.author||'')} · ${esc(x.published||x.date||'')}</p><a href="${safeURL(x.url)}">${esc(t(37))} ↗</a></article>`).join('');$('method').innerHTML=`<article><h2>${esc(t(13))}</h2><p>${esc(t(22))}: ${esc(date(data.documents.checked_at))}. ${esc(t(23))}</p><a href="https://docs.unfccc.int/event/COP-31">UNFCCC COP 31 ↗</a></article><article><h2>${esc(t(14))}</h2><p>${esc(t(31))}</p><a href="https://cop31.grupotrie.com.br/#hoje">COP31 Monitor ↗</a></article><article><h2>${esc(t(35))}</h2><p lang="en" dir="auto">Document metadata versions are not proof of substantive changes. This prototype does not label adoption without verification, fabricate prior versions, or run the ten-minute collector. Public source snapshots are for interface review only. No private editorial intelligence is included.</p></article>`;route();}
function route(){let id=location.hash.slice(1);if(!['today','texts','pulse','explore'].includes(id))id='today';document.querySelectorAll('.view').forEach(s=>s.hidden=s.id!==id);document.querySelectorAll('[data-tab]').forEach(a=>a.setAttribute('aria-current',a.dataset.tab===id?'page':'false'));}
$('language').addEventListener('change',()=>{lang=$('language').value;render()});$('theme').addEventListener('click',()=>{let on=document.body.classList.toggle('dark');$('theme').setAttribute('aria-pressed',String(on));text('theme',on?t(29):t(28))});$('search').addEventListener('input',()=>{limit=20;docs()});$('body').addEventListener('change',()=>{limit=20;docs()});$('reset').addEventListener('click',()=>{$('search').value='';$('body').value='';limit=20;docs()});$('more').addEventListener('click',()=>{limit+=20;docs()});window.addEventListener('hashchange',route);
Promise.all(['briefing','documents','pulse'].map(async k=>{try{let r=await fetch(dataURL(k),k==='documents'?{cache:'no-store'}:{});if(!r.ok)throw Error(k);const v=await r.json();return k==='documents'?normalizeDocuments(v):v}catch(e){if(k==='documents')return {documents:[],checked_at:null,degraded:true,load_failed:true};throw e}})).then(([briefing,documents,pulse])=>{data={briefing,documents,pulse};render()}).catch(()=>{$('error').hidden=false;text('error',t(38))});
